# Test harness: drives the real monitor code in the CR16 sim. It enters at
# mon_test, not mon_entry: on the device mon_entry recomputes the argument
# pointer from the globals [0x874887]/[0x8748a7] (absolute loadd/loadw, which
# cr16-elf-run mishandles and the sim leaves zero), so mon_test takes the
# already-computed arg pointer in (r5,r4) and shares the rest of the body.
# Flat RAM. Tail strings (NUL-terminated, list ended by a 0xff byte) at
# CASES = 0x50000 (generated by test_monitor.py). One 12-byte record per case
# at OUT = 0x58000, written to stdout at the end:
#   +0 status  1 = at_send_ok, 2 = at_send_error, 0 = neither, 3 = called twice
#   +1 lines   number of at_send_response_line calls
#   +2 value   first vararg (16-bit word at sp) of the last response line
#   +4 fmt     (r3,r2) format pointer of the last response line
#   +8 regs    1 if r7..r9, r12 and sp survived mon_entry
#   +9 begin   number of at_begin calls
# Memory under test: 0x9100.. preset 0x1234 0x5678; 0x41234 preset 0x5a5a.
# NB: cr16-elf-run mishandles absolute-address loadd/stord (`stord (r1,r0),
# 0x57ff0` then `loadd 0x57ff0, ...` reads back garbage), so every data access
# here goes through a register pair. monitor.s has no absolute data accesses.
.set CASES,0x50000
.set OUT,0x58000
.set CUR,0x57ff0            # dword: current record pointer (for the stubs)
.set SAVSP,0x57fe0          # dword: sp before the call

# (r1,r0) = current record pointer
.macro GETCUR
    movd $CUR, (r1,r0)
    loadd 0(r1,r0), (r1,r0)
.endm

.globl _start
_start:
    movd $0x60000, (sp)
    movd $0x9100, (r3,r2)
    movw $0x1234, r0
    storw r0, 0(r3,r2)
    movw $0x5678, r0
    storw r0, 2(r3,r2)
    movd $0x41234, (r3,r2)
    movw $0x5a5a, r0
    storw r0, 0(r3,r2)
    movd $CASES, (r11,r10)      # case cursor (r10/r11 are callee-saved)
    movd $OUT, (r1,r0)
    movd $CUR, (r3,r2)
    stord (r1,r0), 0(r3,r2)
loop:
    loadb 0(r11,r10), r0
    cmpb $0xff, r0
    beq done
    GETCUR                      # clear the record
    movd $0, (r3,r2)
    stord (r3,r2), 0(r1,r0)
    stord (r3,r2), 4(r1,r0)
    stord (r3,r2), 8(r1,r0)
    movw $0x7777, r7            # sentinels in callee-saved registers
    movw $0x6666, r8
    movw $0x4444, r9
    movd $0xc0c0c, (r12)
    movd (sp), (r1,r0)
    movd $SAVSP, (r3,r2)
    stord (r1,r0), 0(r3,r2)
    movd (r11,r10), (r5,r4)     # tail pointer
    movw $0x2c, r2              # command index (unused by the monitor)
    movw $0x10, r3              # syntax type (unused)
    movw $0, r6
    movd $mon_test, (r1,r0)     # dispatcher style: jal through a register
    ashud $-1, (r1,r0)          # holding the table value = address/2
    jal (r1,r0)
    movw $1, r0
    cmpw $0x7777, r7
    bne bad
    cmpw $0x6666, r8
    bne bad
    cmpw $0x4444, r9
    bne bad
    movd (r12), (r3,r2)
    cmpd $0xc0c0c, (r3,r2)
    bne bad
    movd $SAVSP, (r3,r2)
    loadd 0(r3,r2), (r3,r2)
    movd (sp), (r5,r4)
    cmpd (r3,r2), (r5,r4)
    beq regs_done
bad:
    movw $0, r0
regs_done:
    movd $CUR, (r5,r4)
    loadd 0(r5,r4), (r3,r2)
    storb r0, 8(r3,r2)
    addd $12, (r3,r2)
    stord (r3,r2), 0(r5,r4)
skip:                           # advance past this string's NUL
    loadb 0(r11,r10), r0
    addd $1, (r11,r10)
    cmpb $0, r0
    bne skip
    br loop
done:
    GETCUR
    movd $OUT, (r3,r2)
    subd (r3,r2), (r1,r0)
    movw r0, r5                 # len
    movw $1, r2                 # fd 1
    movd $OUT, (r4,r3)
    movd $0x404, (r1,r0)        # write
    excp 8
    movw $0, r2
    movd $0x410, (r1,r0)        # exit
    excp 8

# ---- firmware stubs; they trash r0..r6 like real calls may ----
.macro TRASH
    movw $0x5eed, r4
    movw $0x5eed, r5
    movw $0x5eed, r6
    movw $0x5eed, r1
.endm

.globl at_begin
at_begin:
    GETCUR
    loadb 9(r1,r0), r2
    addb $1, r2
    storb r2, 9(r1,r0)
    TRASH
    jump (ra)

.globl at_send_response_line
at_send_response_line:
    movd (r3,r2), (r5,r4)
    GETCUR
    stord (r5,r4), 4(r1,r0)
    loadw 0(sp), r2             # first vararg
    storw r2, 2(r1,r0)
    loadb 1(r1,r0), r2
    addb $1, r2
    storb r2, 1(r1,r0)
    TRASH
    jump (ra)

.globl at_send_ok
at_send_ok:
    movw $1, r3
    br st_set
.globl at_send_error
at_send_error:
    movw $2, r3
st_set:
    GETCUR
    loadb 0(r1,r0), r2
    cmpb $0, r2
    beq st_store
    movw $3, r3                 # status already set: called twice
st_store:
    storb r3, 0(r1,r0)
    TRASH
    jump (ra)

# A real, linker-placed routine for the =C call test (sim executes .text, not RAM).
.section .callee,"ax"
.globl callee
callee:
    movw $0x2BCD, r0
    jump (ra)
